// Monta a mensagem do fim do dia (HTML do Telegram): agenda do próximo dia útil, e-mails de hoje sem resposta,
// rascunhos, tarefas abertas do ambiente de trabalho e pedidos atrasados. Uma parte que falhar vira um aviso curto,
// sem derrubar o resto.
const cfg = $('Configuração do fim do dia').first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const corta = (s, n) => {
  const t = String(s ?? '').replace(/\s+/g, ' ').trim();
  return t.length > n ? t.slice(0, n - 1) + '…' : t;
};
const resposta = (no) => {
  try {
    return $(no).first()?.json ?? {};
  } catch (e) {
    return { error: { message: 'não rodou' } };
  }
};
const falhou = (r) => Boolean(r.error);
const motivo = (r) => corta(r.error?.message ?? r.error?.description ?? (typeof r.error === 'string' ? r.error : ''), 120);
const avisos = [];
const MAX = Math.min(Math.max(Number(cfg.max_itens) || 8, 1), 15);
const lista = (itens, linha) => itens.slice(0, MAX).map(linha).join('\n') + (itens.length > MAX ? `\n…e mais ${itens.length - MAX}` : '');

// Agenda do próximo dia útil (o Outlook devolve o horário já no fuso do Brasil).
const agenda = resposta('Agenda do próximo dia útil');
const eventos = falhou(agenda) ? [] : (agenda.value ?? []).filter((e) => e && !e.isCancelled);
if (falhou(agenda)) avisos.push(`agenda (${motivo(agenda)})`);
const hora = (dt) => String(dt ?? '').slice(11, 16);
const dataCurta = (iso) => `${iso.slice(8, 10)}/${iso.slice(5, 7)}`;
const alvo = String(cfg.proximo_dia ?? '').slice(0, 10);
// Compromisso de vários dias (férias, viagem...) aparece como "dia todo (até dd/mm)", sem um horário que confunda.
const ultimoDia = (e) => {
  const fim = String(e.end?.dateTime ?? '');
  if (!e.isAllDay && fim.slice(11, 16) !== '00:00') return fim.slice(0, 10);
  const d = new Date(fim.slice(0, 10) + 'T12:00:00Z');
  if (isNaN(d)) return fim.slice(0, 10);
  d.setUTCDate(d.getUTCDate() - 1);
  return d.toISOString().slice(0, 10);
};
const linhaEvento = (e) => {
  const ultimo = ultimoDia(e);
  const variosDias = Boolean(alvo) && (String(e.start?.dateTime ?? '').slice(0, 10) < alvo || ultimo > alvo);
  const quando =
    e.isAllDay || variosDias ? (alvo && ultimo > alvo ? `dia todo (até ${dataCurta(ultimo)})` : 'dia todo') : `${hora(e.start?.dateTime)}–${hora(e.end?.dateTime)}`;
  const local = e.location?.displayName ? ` (${esc(corta(e.location.displayName, 40))})` : '';
  return `• ${quando} ${esc(corta(e.subject || '(sem assunto)', 70))}${local}`;
};

// E-mails de hoje que ainda não foram respondidos nem encaminhados (sem os automáticos e os em que ele está só em cópia).
const eu = resposta('Quem sou eu');
const meuEmail = String(eu.mail || eu.userPrincipalName || '').trim().toLowerCase();
const emails = resposta('E-mails de hoje');
const semResposta = [];
if (falhou(emails)) avisos.push(`e-mails (${motivo(emails)})`);
else {
  // Remetentes automáticos: pelo começo do endereço ou por uma parte do domínio (ex.: avisos@notificacoes.loja.com).
  const AUTOMATICO = /^(no-?reply|nao-?responda|naoresponda|do-?not-?reply|mailer-daemon|postmaster|bounce|notifica|notification|alerta?s?|newsletter|news|marketing|info@|mkt|xml@|nfe@)/;
  const DOMINIO_AUTOMATICO = /@(.+[.-])?(notifica[a-z]*|notifications?|newsletters?|news|mailer|marketing|mkt|bounces?)[.-]/;
  const endereco = (r) => String(r?.emailAddress?.address ?? '').trim().toLowerCase();
  for (const m of emails.value ?? []) {
    const de = endereco(m.from) || endereco(m.sender);
    if (!de || (meuEmail && de === meuEmail) || AUTOMATICO.test(de) || DOMINIO_AUTOMATICO.test(de)) continue;
    // Na Caixa de Entrada Destaques, o que o Outlook separou em "Outros" (propaganda, avisos) não conta.
    if (m.inferenceClassification === 'other') continue;
    const verbo = (m.singleValueExtendedProperties ?? []).find((p) => /0x1081/i.test(String(p.id)));
    if (verbo && ['102', '103', '104'].includes(String(verbo.value))) continue;
    const para = (m.toRecipients ?? []).map(endereco);
    if (meuEmail && para.length && !para.includes(meuEmail)) continue;
    semResposta.push(m);
  }
  semResposta.sort(
    (a, b) => (b.importance === 'high') - (a.importance === 'high') || String(b.receivedDateTime).localeCompare(String(a.receivedDateTime)),
  );
}
const horaLocal = (iso) => {
  const d = new Date(iso);
  return isNaN(d) ? '' : d.toLocaleTimeString('pt-BR', { timeZone: cfg.fuso_horario || 'America/Sao_Paulo', hour: '2-digit', minute: '2-digit' });
};
const linhaEmail = (m) =>
  `• ${horaLocal(m.receivedDateTime)} ${esc(corta(m.from?.emailAddress?.name || m.from?.emailAddress?.address || '', 30))}: ` +
  `${esc(corta(m.subject || '(sem assunto)', 60))}${m.importance === 'high' ? ' ❗' : ''}`;

// Rascunhos na pasta Rascunhos (os mexidos hoje e o total).
const rascunhos = resposta('Rascunhos');
let rascunhosHoje = 0;
let rascunhosTotal = 0;
if (falhou(rascunhos)) avisos.push(`rascunhos (${motivo(rascunhos)})`);
else {
  const todos = rascunhos.value ?? [];
  rascunhosTotal = todos.length;
  rascunhosHoje = todos.filter((r) => String(r.lastModifiedDateTime ?? '') >= String(cfg.inicio_hoje_utc)).length;
}

// Tarefas abertas, só do ambiente de trabalho (sem misturar ambientes).
let tarefas = [];
try {
  tarefas = $('Tarefas abertas')
    .all()
    .map((i) => i.json)
    .filter((t) => t && t.titulo);
} catch (e) {
  avisos.push('tarefas');
}
tarefas.sort((a, b) => String(a.prazo || '9999').localeCompare(String(b.prazo || '9999')));
const linhaTarefa = (t) => {
  const prazo = /^\d{4}-\d{2}-\d{2}/.test(String(t.prazo || '')) ? String(t.prazo).slice(0, 10) : '';
  const marca = !prazo ? '' : prazo < cfg.hoje ? ` ⚠️ atrasada (${dataCurta(prazo)})` : prazo === cfg.hoje ? ' (vence hoje)' : ` (até ${dataCurta(prazo)})`;
  return `• ${esc(corta(t.titulo, 70))}${marca}`;
};

// Pedidos atrasados (base oficial de pedidos), em números.
const pedidos = resposta('Pedidos atrasados');
let blocoPedidos = '';
if (falhou(pedidos) || !pedidos.resumo) avisos.push(`pedidos (${motivo(pedidos) || corta(pedidos.erro, 120) || 'sem resposta da base'})`);
else {
  const r = pedidos.resumo;
  const unidades = (r.por_unidade ?? [])
    .slice(0, 4)
    .map((u) => `${esc(corta(u.valor, 25))}: ${u.itens}`)
    .join(' · ');
  blocoPedidos = r.itens
    ? `📦 <b>Pedidos atrasados: ${r.itens} ${r.itens === 1 ? 'item' : 'itens'}</b> em ${r.pedidos} ${r.pedidos === 1 ? 'pedido' : 'pedidos'}` +
      (unidades ? `\n${unidades}` : '')
    : '📦 <b>Pedidos atrasados:</b> nenhum';
  const atualizada = /atualizada em (.+)$/.exec(String(pedidos.fonte ?? ''))?.[1];
  if (atualizada) blocoPedidos += `\n<i>Base de ${esc(atualizada)}</i>`;
}

const partes = [
  `🌙 <b>Fim do dia, ${esc(cfg.nome_dono)}!</b> ${esc(cfg.hoje_extenso)}`,
  `📅 <b>${esc(cfg.proximo_dia_rotulo)}</b>\n` + (falhou(agenda) ? 'Não consegui ler a agenda.' : eventos.length ? lista(eventos, linhaEvento) : 'Nada na agenda.'),
  `📬 <b>E-mails de hoje sem resposta: ${falhou(emails) ? '?' : semResposta.length}</b>` + (semResposta.length ? `\n${lista(semResposta, linhaEmail)}` : ''),
  falhou(rascunhos)
    ? ''
    : `📝 <b>Rascunhos para revisar:</b> ${rascunhosHoje} de hoje` +
      (rascunhosTotal > rascunhosHoje ? `, ${rascunhosTotal >= 50 ? '50 ou mais' : rascunhosTotal} na pasta` : ''),
  `✅ <b>Tarefas abertas (${esc(cfg.ambiente_nome)}): ${tarefas.length}</b>` + (tarefas.length ? `\n${lista(tarefas, linhaTarefa)}` : ''),
  blocoPedidos,
  avisos.length ? `⚠️ <i>Não consegui ler: ${esc(avisos.join('; '))}.</i>` : '',
  'Bom descanso! 😊',
].filter(Boolean);
const html = partes.join('\n\n');
return [
  {
    json: {
      html,
      texto_simples: html.replace(/<[^>]+>/g, ''),
      contagens: {
        eventos: eventos.length,
        emails_sem_resposta: falhou(emails) ? null : semResposta.length,
        rascunhos_hoje: rascunhosHoje,
        tarefas: tarefas.length,
        pedidos_atrasados: pedidos?.resumo?.itens ?? null,
      },
      avisos,
    },
  },
];
